-- !!! LOCAL DEMO ONLY. DO NOT RUN THIS ON A LIVE / MULTI-USER DATABASE. !!!
-- This file DELETES solved_questions rows for question ids 101-300 for EVERY user
-- before re-creating the demo history. For a public database use
-- database/seed_question_bank.sql, which never deletes anything.
--
-- LeetTrack demo seed data (Striver 450 -style sample set, ~200 questions)
--
-- 200 real DSA problems (Array/String/LinkedList/Stack/Tree/BST/Graph/DP/
-- Greedy/Backtracking/Trie/Heap/Matrix/Design/Bit Manipulation/Math)
-- covering every feature the app has to show:
--   - unsolved questions          -> feed the "new question" pool
--   - solved, 0 revisions yet     -> waiting on their 1st revision
--   - solved, 1 revision done     -> waiting on their 2nd revision
--   - solved, 2 revisions done    -> waiting on a later revision (Medium/Hard)
--   - fully revised (exhausted)   -> revision_counter has hit the difficulty's
--                                    limit, due_date is NULL, nothing more owed
--
-- Counts: 72 unsolved,
-- 38 at 0 revisions,
-- 38 at 1 revision,
-- 20 at 2 revisions,
-- 32 fully revised.
--
-- All solved_date / last_revision_date values are generated relative to
-- CURDATE() -- spread across the last ~1 month (including today, yesterday,
-- and the day before yesterday), and due_date is computed with the exact
-- same formula as engine.py (baseline days doubling per revision), so the
-- dashboard, due-revisions queue, and the "simulated date" viewer all behave
-- exactly as they would on a real account -- just re-run this file any day
-- and the whole story (overdue / due today / due later / already unsolved)
-- regenerates relative to that day.
--
-- Safe to re-run: it only touches question_id 101-300 and the demo
-- user, so it never touches any other data already in your database.

USE leetcode_tracker;


DELETE FROM solved_questions WHERE question_id BETWEEN 101 AND 300;
DELETE FROM question_bank WHERE question_id BETWEEN 101 AND 300;

-- Also clear the original tiny demo range (201-206) in case it's still around
-- from an earlier version of this seed file.
DELETE FROM solved_questions WHERE question_id IN (201, 202, 203, 204, 205, 206);
DELETE FROM question_bank WHERE question_id IN (201, 202, 203, 204, 205, 206);

